def _design():
    g = [["T_W" if (x in (0, 39) or y in (0, 25)) else "EMPTY" for x in range(W_)] for y in range(H_)]
    # sealed vault: only through the plate gate
    g[13][37] = "V"
    g[12][37] = "T_W"
    g[14][37] = "T_W"
    g[13][36] = "P_GATE"
    g[3][16] = "K1"
    g[22][16] = "K2"
    # ice highway on row 13 ending in a pit
    for x in range(5, 32):
        g[13][x] = "ICE"
    g[13][32] = "PIT"
    # ice drop between the keys ending in a pit right above K2
    for y in range(5, 21):
        g[y][16] = "ICE"
    g[21][16] = "PIT"
    # two sokoban plates
    g[8][28] = "BOX"
    g[6][30] = "PLATE"
    g[18][28] = "BOX"
    g[20][30] = "PLATE"
    # dual-period laser curtains on the vault approach column
    g[1][33] = "LASER_D"
    g[24][33] = "LASER2_U"
    return g


AUTHOR_SOLUTION = []


def build_dungeon() -> dict:
    g = _design()
    return {"taunt": "压板只认箱子，金库只认活人。", "grid": g, "author_solution": list(AUTHOR_SOLUTION)}
